//! Writes the mux wire TypeScript bindings to `schema/ts/`. The checked-in
//! copy is `schema/ts/`; CI regenerates it into a temp dir and fails on a
//! diff, so the bindings cannot drift from the types.
//!
//! ```text
//! cargo run --features ts --example gen-ts
//! ```

use fno_proto::{ClientMsg, ServerMsg, MIN_COMPAT_PROTO, PROTO_VERSION};
use std::fs;
use std::path::{Path, PathBuf};
use ts_rs::{Config, TS};

/// The marker the generated-artifacts manifest and the write-gate key on.
/// It rides the first line of every emitted file.
const HEADER: &str =
    "// Generated by crates/fno-proto/examples/gen-ts.rs from the fno-proto wire types; do not edit.";

fn main() {
    let out_dir = std::env::args()
        .nth(1)
        .map(PathBuf::from)
        .unwrap_or_else(|| Path::new(env!("CARGO_MANIFEST_DIR")).join("schema/ts"));

    fs::create_dir_all(&out_dir).expect("output dir creates");
    // A removed wire type must not leave a stale binding behind, so the
    // previous run's .ts files go first. Nothing outside the dir is touched.
    for entry in fs::read_dir(&out_dir).expect("output dir reads") {
        let path = entry.expect("dir entry").path();
        if path.extension().is_some_and(|e| e == "ts") {
            fs::remove_file(&path).expect("stale binding removes");
        }
    }

    // The wire is JSON: u64 ids ride as plain JSON numbers, so the ts-rs
    // bigint default would lie about what JSON.parse hands a client.
    let cfg = Config::default()
        .with_out_dir(out_dir.clone())
        .with_large_int("number");
    ClientMsg::export_all(&cfg).expect("ClientMsg bindings export");
    ServerMsg::export_all(&cfg).expect("ServerMsg bindings export");

    fs::write(
        out_dir.join("version.ts"),
        format!(
            "{HEADER}\n// The wire generation the bindings speak; keep in lockstep with the consts in src/lib.rs.\nexport const PROTO_VERSION: number = {PROTO_VERSION};\nexport const MIN_COMPAT_PROTO: number = {MIN_COMPAT_PROTO};\n"
        ),
    )
    .expect("version.ts writes");

    let mut names: Vec<String> = fs::read_dir(&out_dir)
        .expect("output dir reads")
        .map(|e| {
            e.expect("dir entry")
                .file_name()
                .to_string_lossy()
                .into_owned()
        })
        .filter(|n| n.ends_with(".ts") && n != "index.ts")
        .collect();
    names.sort();
    let index = names
        .iter()
        .map(|n| format!("export * from \"./{}\";", n.trim_end_matches(".ts")))
        .collect::<Vec<_>>()
        .join("\n");
    fs::write(out_dir.join("index.ts"), format!("{HEADER}\n{index}\n")).expect("index.ts writes");

    // The per-type files ts-rs emits carry no header, so the generated
    // marker is prepended after the fact. version.ts and index.ts wrote
    // their own above.
    for entry in fs::read_dir(&out_dir).expect("output dir reads") {
        let path = entry.expect("dir entry").path();
        let name = path.file_name().map(|n| n.to_os_string());
        if path.extension().is_some_and(|e| e == "ts")
            && name
                .as_ref()
                .is_some_and(|n| n != "index.ts" && n != "version.ts")
        {
            let body = fs::read_to_string(&path).expect("binding reads");
            fs::write(&path, format!("{HEADER}\n{body}")).expect("binding header prepends");
        }
    }

    println!("ts bindings -> {}", out_dir.display());
}
